(async () => {
const d=load("p56-budget-descriptor");
const q={cmd:"python3 -B -c 'print(123456789)'",max_output_tokens:18000,yield_time_ms:10000};
const exact="// @exec: {\"max_output_tokens\": 18000}\nawait eval(load(\"p56-budget-probe-source\"));";
const check=(o,n)=>!o.code.startsWith("// @exec: {\"max_output_tokens\": 18000}\n")?"OUTER_BUDGET_INVALID":n.max_output_tokens!==18000?"NESTED_BUDGET_INVALID":"BUDGET_REQUEST_VALID";
if(d.code!==exact||d.tool!=="functions.exec")throw Error("OUTER_SOURCE_INVALID");
const tests=[[d,q,"BUDGET_REQUEST_VALID"],[{...d,code:d.code.split("\n").slice(1).join("\n")},q,"OUTER_BUDGET_INVALID"],[{...d,code:d.code.replace("18000","10000")},q,"OUTER_BUDGET_INVALID"],[d,{cmd:q.cmd},"NESTED_BUDGET_INVALID"],[d,{...q,max_output_tokens:10000},"NESTED_BUDGET_INVALID"]];
for(const [o,n,e]of tests)if(check(o,n)!==e)throw Error("BUDGET_CASE_FAILED");
store("p56-budget-expected-cases",JSON.stringify(tests));
const r=await tools.exec_command(q);
store("p56-budget-original",r);
store("p56-budget-record",JSON.stringify({outer:d,probe_source:load("p56-budget-probe-source"),nested_request:q,actual_result:r,effective_provider_budget:null}));
if(r.exit_code!==0||r.session_id!==undefined||r.output!=="123456789\n")throw Error("ACTUAL_RECEPTION_INVALID");
store("p56-budget-ready",true);
text(JSON.stringify({budget_request:18000,nested_request:18000,actual_exit:0,actual_bytes:10,provider_effective_budget:"unavailable",capture_authority:false}));
})();

