import os, stat, json, hashlib, subprocess, math
from pathlib import Path
root=Path.cwd()
roots=sorted([p for p in Path("build").iterdir() if p.name.startswith("phase16") and p.is_dir() and not p.is_symlink()]+[Path(".planning/phases/16-host-evidence-and-roadmap")],key=lambda p:p.as_posix())
count=0
path_bytes=0
mode_zero=[]
types={}
shape_bytes=3
for base in roots:
    paths=[base]
    for current, dirs, files in os.walk(base,topdown=True,followlinks=False):
        dirs.sort()
        files.sort()
        for name in dirs+files:
            paths.append(Path(current)/name)
        dirs[:]=[n for n in dirs if not (Path(current)/n).is_symlink()]
    for p in paths:
        s=p.lstat()
        t=stat.S_IFMT(s.st_mode)
        mode=stat.S_IMODE(s.st_mode)
        types[str(t)]=types.get(str(t),0)+1
        name=p.as_posix()
        count+=1
        path_bytes+=len(json.dumps(name,ensure_ascii=True).encode())
        row={"type":t,"mode":mode}
        if stat.S_ISREG(s.st_mode):
            row["size"]=s.st_size
            if mode & 0o444:
                row["sha256"]="0"*64
            else:
                mode_zero.append({"path":name,"type":t,"mode":mode,"size":s.st_size,"mtime_ns":s.st_mtime_ns,"ctime_ns":s.st_ctime_ns})
        elif stat.S_ISLNK(s.st_mode):
            row["target"]=os.readlink(p)
        shape_bytes+=len(json.dumps(name,ensure_ascii=True).encode())+1+len(json.dumps(row,sort_keys=True,separators=(",",":"),ensure_ascii=True).encode())+1
dirty=[".planning/config.json","README.md","include/nesturbator.h","tests/retroarch/interruption_trace.sh","tests/retroarch/state_session.sh","tests/retroarch/test_state_session.sh"]
b={"head":subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip(),"branch":subprocess.check_output(["git","branch","--show-current"],text=True).strip(),"index_sha256":hashlib.sha256(Path(".git/index").read_bytes()).hexdigest(),"staged":subprocess.check_output(["git","diff","--cached","--name-only"],text=True),"dirty":{n:hashlib.sha256(Path(n).read_bytes()).hexdigest() for n in dirty}}
out={"purpose":"administrative-sizing-only","capture_authority":False,"root_count":len(roots),"entry_count":count,"types":types,"serialized_path_key_bytes":path_bytes,"compact_metadata_shape_bytes_with_placeholder_hashes":shape_bytes,"hashes_are_placeholders":True,"full_content_inventory":False,"metadata_only":mode_zero,"minimum_base64_packets_for_shape":math.ceil(shape_bytes/12288),"minimum_READ_COMPARE_ACK_calls_for_shape":4*math.ceil(shape_bytes/12288),"minimum_32packet_outer_calls_for_shape":2*math.ceil(math.ceil(shape_bytes/12288)/32),"limitations":["Metadata projection only; content hashes are zero placeholders","Actual future capture, schema and framing add bytes","No READ/COMPARE/ACK or bound acceptance","No historical byte comparison"],"baseline":b}
print(json.dumps(out,sort_keys=True,separators=(",",":")))
